    def get_shape_coords(color):
        """Get all coordinates of a specific color"""
        coords = []
        for y in range(h):
            for x in range(w):
                if grid[y][x] == color:
                    coords.append((y, x))
        return coords

    colors = set()
    for y in range(h):
        for x in range(w):
            if grid[y][x] > 0 and grid[y][x] not in colors:
                colors.add(grid[y][x])

